import numpy as np, cv2
p=np.load('pixels.npz')['pixels'];a=np.stack([(p>>16)&255,(p>>8)&255,p&255],-1).transpose(2,0,1,3).astype(np.uint8)
for i in [0,1,10,20,30,36,40,60,95]:
 hsv=cv2.cvtColor(a[i],cv2.COLOR_RGB2HSV)
 masks={'B':(hsv[:,:,1]>55)&(hsv[:,:,0]>85)&(hsv[:,:,0]<115),'R':(hsv[:,:,1]>45)&((hsv[:,:,0]<10)|(hsv[:,:,0]>170)),'Y':(hsv[:,:,1]>45)&(hsv[:,:,0]>=15)&(hsv[:,:,0]<40)}
 print('\\n',i)
 for k,m in masks.items():
  num,lab,stats,cent=cv2.connectedComponentsWithStats(m.astype(np.uint8),8);cs=[]
  for j in range(1,num):
   x,y,w,h,area=stats[j]
   if area>8:cs.append((area,(x,y,w,h),tuple(np.round(cent[j],1))))
  print(k,sorted(cs,reverse=True)[:5])
PY"
